 * 1. Member registration and authentication works correctly
 * 2. Display name update reflects immediately in the response
 * 3. Other fields (email, created_at) remain unchanged
 * 4. updated_at timestamp is refreshed on modification
 * 5. Partial update only modifies specified fields
 */
export async function test_api_member_profile_display_name_update(
  connection: api.IConnection,
