/**
 * Test that members cannot update another member's profile - enforces complete data privacy isolation.
 *
 * **Setup**:
 * 1. Register first member account via POST /todoApp/auth/member/join (Member A)
 * 2. Register second member account via POST /todoApp/auth/member/join (Member B)
 * 3. Capture both member IDs - the test will authenticate as Member A but attempt to update Member B's profile
 *
 * **Test Execution**:
 * 1. Authenticate the test session as Member A (use Member A's session token)
 * 2. Call PUT /todoApp/members/{memberId} with Member B's ID in the path parameter (not Member A's ID)
 * 3. Request body contains a display_name update
 * 4. Verify the request is rejected with authorization error
 *
 * **Business Logic Validation**:
 * - The memberId path parameter must match the authenticated user's ID
 * - Cross-user profile updates must be rejected without revealing information about other accounts
 * - Error response should not disclose whether the target memberId exists or belongs to another user
 * - Complete data privacy isolation between user accounts must be enforced
 */
export async function test_api_member_profile_cross_user_access_denial(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register Member A (the attacker in this scenario)
  const memberA = await authorize_member_join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      displayName: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies ITodoAppMember.IJoin,
  });
  typia.assert(memberA);
  // 2. Register Member B (the target whose profile update will be attempted)
  const memberB = await authorize_member_join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      displayName: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies ITodoAppMember.IJoin,
  });
  typia.assert(memberB);
  // 3. Create member A's connection with authentication token
  const memberAConnection: api.IConnection = {
    host: connection.host,
    headers: {
      Authorization: memberA.token.access,
    },
  };
  // 4. Attempt to update Member B's profile using Member A's credentials (should fail)
  const newDisplayName = RandomGenerator.name();
  await TestValidator.error("cross-user profile update denied", async () => {
    await api.functional.todoApp.members.update(memberAConnection, {
      memberId: memberB.id, // Using Member B's ID, not Member A's
      body: {
        display_name: newDisplayName,
      } satisfies ITodoAppMember.IUpdate,
    });
  });
