export async function patchTodoAppMemberTodos(props: {
  member: MemberPayload;
  body: ITodoAppTodo.IRequest;
}): Promise<IPageITodoAppTodo.ISummary> {
  const page = props.body.page ?? 1;
  const limit = Math.min(props.body.limit ?? 20, 100);
  const skip = (page - 1) * limit;
  const whereInput = {
    member_id: props.member.id,
    ...(props.body.deleted
      ? { deleted_at: { not: null } }
      : { deleted_at: null }),
    ...(props.body.completed !== undefined && {
      completed: props.body.completed,
    }),
    ...(props.body.search && { title: { contains: props.body.search } }),
  } satisfies Prisma.todo_app_todosWhereInput;
  const sortField = props.body.sort ?? "created_at";
  const direction = props.body.direction ?? "DESC";
  const sortDirection = direction === "ASC" ? "asc" : "desc";
  const orderByInput =
    sortField === "start_date" || sortField === "due_date"
      ? [{ [sortField]: { sort: sortDirection, nulls: "last" } }]
      : ({
          [sortField]: sortDirection,
        } satisfies Prisma.todo_app_todosOrderByWithRelationInput);
  const data = await MyGlobal.prisma.todo_app_todos.findMany({
    where: whereInput,
    skip,
    take: limit,
    orderBy: orderByInput,
    ...TodoAppTodoAtSummaryTransformer.select(),
  });
  const total = await MyGlobal.prisma.todo_app_todos.count({
    where: whereInput,
  });
  return {
    data: await ArrayUtil.asyncMap(
      data,
      TodoAppTodoAtSummaryTransformer.transform,
    ),
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
  } satisfies IPageITodoAppTodo.ISummary;
}

